function solve(input) {
  const { nums } = input;
  if (nums.length === 0) return 0;
  if (nums.length === 1) return nums[0];
  let prev2 = 0, prev1 = 0;
  for (const n of nums) {
    const temp = Math.max(prev1, prev2 + n);
    prev2 = prev1;
    prev1 = temp;
  }
  return prev1;
}
